46	static void print_cpu_configuration()
47	{
48	  // these symbols are defined in obj_sc/config.o
49	  // they come from andes_ip/kv_core/top/hdl/config.inc
50	  char* start = &_binary_config_inc_start;
51	  char* end = &_binary_config_inc_end;
52	  fwrite(start, 1, end - start, stdout);
53	}
54	
55	// Emit the QEMU `-readconfig` cfg baked from this engine's config.inc, so the
56	// hybrid fast-forward leg (QEMU) runs the same ISA this engine models. The
57	// andesim driver captures this and passes it to QEMU via -readconfig; an engine
58	// built without a converter emits nothing, and the driver keeps its -cpu.
59	static void print_qemu_config()
60	{
61	  char* start = &_binary_qemu_cfg_start;
62	  char* end = &_binary_qemu_cfg_end;
63	  fwrite(start, 1, end - start, stdout);
64	}
65	
66	// Emit the andes-sim engine descriptor (see docs/engine_interface.md). This is
67	// the self-describe half of the framework's hot-plug contract: andes-sim runs
68	// `sim_<cfg> --describe`, parses this JSON, and can then drive the binary with
69	// no per-engine code. vlen/xlen come from the same embedded config.inc blob
70	// that --print-config dumps; the config name comes from VSIM_CPU_PYMODULE_NAME.
71	static void describe_engine()
72	{
73	  std::string cfg = VSIM_CPU_PYMODULE_NAME;  // "simulator_<cfg>"
74	  const std::string prefix = "simulator_";
75	  if (cfg.starts_with(prefix))
76	    cfg = cfg.substr(prefix.size());
77	
78	  const std::string_view blob(&_binary_config_inc_start,
79	                              static_cast<size_t>(&_binary_config_inc_end
80	                                                  - &_binary_config_inc_start));
81	  auto scan_int = [blob](std::string_view key) -> long {
82	    size_t pos = blob.find(key);
83	    if (pos == std::string_view::npos)
84	      return 0;
85	    pos += key.size();
86	    while (pos < blob.size() && (blob[pos] < '0' || blob[pos] > '9'))
87	      ++pos;
88	    long v = 0;
89	    while (pos < blob.size() && blob[pos] >= '0' && blob[pos] <= '9')
90	      v = v * 10 + (blob[pos++] - '0');
91	    return v;
92	  };
93	  const long vlen = scan_int("NDS_VLEN");
94	  const long dlen = scan_int("NDS_DLEN");
95	  const long elen = scan_int("NDS_ELEN");
96	  const long xlen = scan_int("NDS_XLEN");
97	  // Hart-0 local memories, reported in BYTES (the config macro is KB). The
98	  // descriptor's sizes mean "LM content TRANSPORT supported at this size":
99	  // the driver passes --ilm/--dlm whenever they are > 0 and expects the exit
100	  // sidecars back, so an engine must implement the FULL backdoor pair (load
101	  // for resume AND dump for the exit drain -- the kCpuCan* authorities in
102	  // simulator.hpp) to advertise; 0 = no memory or no backdoor (e.g.
103	  // ax46mpv_advanced today: config has the memories, wrapper has no
104	  // set_/get_), and the driver arms nothing.
105	  using CPU = VSIM_CPU_INTERFACE_CLASS;
106	  const long ilm_size = kCpuCanLoadIlm<CPU> && kCpuCanDumpIlm<CPU>
107	                          ? scan_int("NDS_ILM_SIZE_KB") * 1024 : 0;
108	  const long dlm_size = kCpuCanLoadDlm<CPU> && kCpuCanDumpDlm<CPU>
109	                          ? scan_int("NDS_DLM_SIZE_KB") * 1024 : 0;
110	  // Cluster-level HVM, same transport contract (--hvm in, .hvm sidecar out).
111	  const long hvm_size = kCpuCanLoadHvm<CPU> && kCpuCanDumpHvm<CPU>
112	                          ? scan_int("NDS_HVM_SIZE_KB") * 1024 : 0;
113	
114	  // Built by hand (not fmt) to keep the literal {bin}/{elf}/{state_in}
115	  // placeholders out of fmt's brace parser.
116	  std::string json;
117	  json += "{\n";
118	  json += "  \"id\": \"verilator:" + cfg + "\",\n";
119	  json += "  \"type\": \"verilator\",\n";
120	  json += "  \"kind\": \"cycle-accurate\",\n";
121	  json += "  \"vlen\": " + std::to_string(vlen) + ", \"dlen\": "
122	          + std::to_string(dlen) + ", \"elen\": " + std::to_string(elen)
123	          + ", \"xlen\": " + std::to_string(xlen) + ",\n";
124	  json += "  \"ilm_size\": " + std::to_string(ilm_size) + ", \"dlm_size\": "
125	          + std::to_string(dlm_size) + ", \"hvm_size\": "
126	          + std::to_string(hvm_size) + ",\n";
127	  json += "  \"triggers\": [\"csr\", \"pc\"],\n";
128	  json += "  \"roles\": [\"standalone\", \"accurate-leg\"],\n";
129	  json += "  \"state\": [\"resume\", \"drain\"],\n";
130	  // Andes custom CSRs this core actually implements (from its config.inc).
131	  // The driver uses this to skip --verify on CSRs the engine lacks, mirroring
132	  // the resume/drain gating in ResumeDriver/StateDrain (single binder).
133	  const std::vector<std::string> andes_csrs =
134	      hybrid::supported_andes_csr_names(hybrid::andes_caps_from_config());
135	  json += "  \"andes_csrs\": [";
136	  for (size_t i = 0; i < andes_csrs.size(); ++i)
137	    json += (i ? ", \"" : "\"") + andes_csrs[i] + "\"";
138	  json += "],\n";
139	  json += "  \"invoke\": {\n";
140	  json += "    \"standalone\": [\"{bin}\", \"{elf}\"],\n";
141	  json += "    \"accurate-leg\": [\"{bin}\", \"{elf}\", "
142	          "\"--resume-from-qemu\", \"{state_in}\", "
143	          "\"--handoff-out\", \"{state_out}\", "
144	          "\"--shared-mem-path\", \"{mmap}\", "
145	          "\"--shared-mem-size\", \"{mmap_size}\", "
146	          "\"--shared-mem-base\", \"{mmap_base}\"]\n";
147	  json += "  },\n";
148	  json += "  \"result\": \"stderr:cycles\"\n";
149	  json += "}\n";
150	  fwrite(json.data(), 1, json.size(), stdout);
151	}
