244	// F3 probe helpers -- kept OUT of the generic sc_main lambda so their
245	// structured-binding / iostream / fmt code is compiled once, not re-instantiated
246	// per CPU class (a per-CPU instantiation inside the generic lambda tripped a
247	// clang ICE).
248	static auto read_probe_list(const std::string& path) -> std::vector<uint16_t>
249	{
250	  std::ifstream pf{path};
251	  if (!pf)
252	    throw std::runtime_error("--probe: cannot open " + path);
253	  std::vector<uint16_t> addrs;
254	  for (std::string line; std::getline(pf, line);) {
255	    const auto b = line.find_first_not_of(" \t\r");
256	    if (b == std::string::npos || line[b] == '#') continue;
257	    addrs.push_back(
258	      static_cast<uint16_t>(std::stoul(line.substr(b), nullptr, 16)));
259	  }
260	  return addrs;
261	}
