263	static void emit_probe_csv(
264	  const std::vector<std::pair<uint16_t, std::optional<uint64_t>>>& results)
265	{
266	  for (const auto& r: results) {
267	    if (r.second)
268	      fmt::print("0x{:03X},yes,0x{:016x}\n", r.first, *r.second);
269	    else
270	      fmt::print("0x{:03X},no,-\n", r.first);
271	  }
272	}
