1	// CsrTrigger pre-scans an instruction buffer (typically the loadable
2	// executable segments of an ELF) for the marker HINTs (slti x0, x0,
3	// 0x5A0/0x5A1) and records their PCs. At retire time the simulator
4	// queries lookup(pc) to decide whether to drain state at the trigger.
5	//
6	// Pure logic: no SystemC, no DMI bus.
7	
8	#pragma once
9	
10	#include "hybrid/insn_match.h"
11	
12	#include <cstddef>
13	#include <cstdint>
14	#include <cstring>
15	#include <optional>
16	#include <span>
17	#include <unordered_map>
18	
19	namespace hybrid
20	{
21	
22	struct CsrTriggerHit
23	{
24	  hybrid_handoff_kind kind;
25	  uint32_t insn;
26	};
27	
28	class CsrTrigger
29	{
30	public:
31	  void scan_buffer(std::span<const uint8_t> code, uint64_t base_pc)
32	  {
33	    std::size_t i = 0;
34	    while (i + sizeof(uint16_t) <= code.size()) {
35	      uint16_t lo = 0;
36	      std::memcpy(&lo, code.data() + i, sizeof(lo));
37	
38	      const bool is_32 = (lo & 0x3u) == 0x3u;
39	      if (is_32) {
40	        if (i + sizeof(uint32_t) > code.size()) break;
41	        uint32_t insn = 0;
42	        std::memcpy(&insn, code.data() + i, sizeof(insn));
43	        hybrid_handoff_kind kind = HYBRID_HANDOFF_NONE;
44	        if (hybrid_match_handoff_insn(insn, &kind)) {
45	          hits_.insert_or_assign(base_pc + i, CsrTriggerHit{kind, insn});
46	        }
47	        i += sizeof(uint32_t);
48	      } else {
49	        i += sizeof(uint16_t);
50	      }
51	    }
52	  }
53	
54	  // PC-trigger mode: insert a synthetic hit without scanning. Used when the
55	  // orchestrator passes --hybrid-exit-pc on the CLI; in that case the binary
56	  // need not contain a marker HINT, and `insn` is unused (HandoffController
57	  // dispatches on `kind` alone; PC mode only inserts EXIT).
58	  void add_pc_hit(uint64_t pc, hybrid_handoff_kind kind)
59	  {
60	    hits_.insert_or_assign(pc, CsrTriggerHit{kind, /*insn=*/0u});
61	  }
62	
63	  auto lookup(uint64_t pc) const -> std::optional<CsrTriggerHit>
64	  {
65	    if (auto it = hits_.find(pc); it != hits_.end()) return it->second;
66	    return std::nullopt;
67	  }
68	
69	private:
70	  std::unordered_map<uint64_t, CsrTriggerHit> hits_;
71	};
72	
73	}  // namespace hybrid
