13	inline auto load_state(const std::string& path) -> HybridState
14	{
15	  std::ifstream f(path, std::ios::binary);
16	  if (!f)
17	    throw std::runtime_error("hybrid::load_state: cannot open " + path);
18	
19	  HybridState s{};
20	  f.read(reinterpret_cast<char*>(&s), sizeof(s));
21	  if (f.gcount() != static_cast<std::streamsize>(sizeof(s)))
22	    throw std::runtime_error("hybrid::load_state: short read on " + path);
23	
24	  if (s.magic != HYBRID_STATE_MAGIC)
25	    throw std::runtime_error("hybrid::load_state: bad magic in " + path);
26	  if (s.version != HYBRID_STATE_VERSION)
27	    throw std::runtime_error("hybrid::load_state: unsupported version in "
28	                             + path);
29	  // L11: vreg[] holds HYBRID_VLEN_BYTES_MAX bytes per register; a live V
30	  // state claiming more cannot have been drained without truncation.
31	  if ((s.flags & HYBRID_FLAG_V) && s.vlenb > HYBRID_VLEN_BYTES_MAX)
32	    throw std::runtime_error("hybrid::load_state: vlenb "
33	                             + std::to_string(s.vlenb)
34	                             + " exceeds HYBRID_VLEN_BYTES_MAX in " + path);
35	  return s;
36	}
