44	  static constexpr uint16_t kCsrPmpaddr0 = 0x3B0;
45	  static constexpr uint16_t kCsrFcsr     = 0x003;
46	  static constexpr uint16_t kCsrMstatus  = 0x300;
47	  static constexpr uint16_t kCsrMie      = 0x304;
48	  static constexpr uint16_t kCsrMtvec    = 0x305;
49	  static constexpr uint16_t kCsrMscratch = 0x340;
50	  static constexpr uint16_t kCsrMepc     = 0x341;
51	  static constexpr uint16_t kCsrMcause   = 0x342;
52	  static constexpr uint16_t kCsrMtval    = 0x343;
53	  static constexpr uint16_t kCsrMip      = 0x344;
54	  static constexpr uint16_t kCsrMcycle   = 0xB00;
55	  static constexpr uint16_t kCsrMinstret = 0xB02;
56	  // Andes machine setup CSRs crt0 writes at boot (see hybrid_state_v1):
57	  // mcache_ctl enables the L1 I/D caches, mmisc_ctl holds misc machine config.
58	  static constexpr uint16_t kCsrMcacheCtl = 0x7CA;
59	  static constexpr uint16_t kCsrMmiscCtl  = 0x7D0;
60	  static constexpr uint16_t kCsrVstart   = 0x008;
61	  static constexpr uint16_t kCsrVxsat    = 0x009;
62	  static constexpr uint16_t kCsrVxrm     = 0x00A;
63	  static constexpr uint16_t kCsrVcsr     = 0x00F;
64	  static constexpr uint16_t kCsrVtype    = 0xC21;
65	  static constexpr uint16_t kCsrVl       = 0xC20;
66	
67	  static constexpr uint32_t kDmcontrolDmactive  = 1u << 0;
68	  static constexpr uint32_t kDmcontrolResumereq = 1u << 30;
69	  static constexpr uint32_t kDmcontrolHaltreq   = 1u << 31;
70	
71	  static constexpr uint32_t kDmstatusAllhalted    = 1u << 9;
72	  static constexpr uint32_t kDmstatusAllresumeack = 1u << 17;
73	
74	  static constexpr uint32_t kAbstractcsBusy       = hybrid::kAbstractcsBusy;
75	  static constexpr uint32_t kAbstractcsCmderrMask = hybrid::kAbstractcsCmderrMask;
76	
77	  // mstatus extension-state fields: FS (bits 14:13), VS (bits 10:9).
78	  // "Initial" (01) is the minimal enable the abstract FPR / V writes require.
79	  static constexpr uint64_t kMstatusFsMask    = 0x6000ULL;
80	  static constexpr uint64_t kMstatusFsInitial = 0x2000ULL;
81	  static constexpr uint64_t kMstatusVsMask    = 0x600ULL;
82	  static constexpr uint64_t kMstatusVsInitial = 0x200ULL;
83	
84	  static constexpr unsigned kPollIterations = kDmiPollIterations;
85	
86	  // scratch_gpa: the GUEST address of the V-register transport page (L26:
87	  // v_scratch_gpa(ram_base, ram_size) = the mmap's top page). Defaults to the
88	  // "unset" sentinel; a non-V resume never reads it. The simulator passes the
89	  // real value from platform.main_memory.
90	  explicit ResumeDriver(DmiBus& bus, uint64_t scratch_gpa = kVScratchGpaUnset,
91	                        AndesCaps caps = AndesCaps::all())
92	      : bus_{bus}, scratch_gpa_{scratch_gpa}, caps_{caps}
93	  {}
94	
95	  // LG1/LG2 (liveness gate): supply the engine's own reset-state drain.
96	  // Restores whose drained value equals this baseline are skipped -- the
97	  // write would be a no-op, and every DM operation costs hundreds of
98	  // simulated cycles. LG1 gates each tolerant CSR write; LG2 elides the FPR
99	  // and V data blocks as whole blocks when byte-equal. Unset (default) keeps
100	  // transport-everything. Always-live state (mstatus, GPRs, dpc, dcsr,
101	  // mcycle, minstret, the S/U PMP mirror) is never gated.
102	  //
103	  // v_cfg_at_reset: pass false when the baseline was CAPTURED this run --
104	  // the capture drain's V dump sweep already clobbered the hart's
105	  // vtype/vl/vstart, so their baseline equality no longer proves the
106	  // architectural vsetvl redundant. Cache-hit runs (pristine hart) pass true.
107	  void set_reset_baseline(const hybrid_state_v1& b, bool v_cfg_at_reset = true)
108	  {
109	    baseline_ = b;
110	    has_baseline_ = true;
111	    v_cfg_at_reset_ = v_cfg_at_reset;
112	  }
113	
114	  // Number of register-restore operations elided by the reset baseline this
115	  // resume: one per gated CSR write, 32 per elided FPR/V data block, one per
116	  // elided vsetvl.
117	  auto baseline_skip_count() const -> uint64_t { return baseline_skip_count_; }
118	
119	  // v5: declare whether the target engine has an L2 cache controller, and its
120	  // MMIO register base. Off by default so an engine without an L2C (every
121	  // current build: NDS_L2C_CACHE_SIZE_KB=0) issues NO L2C store even if the
122	  // handoff carries the block -- a store to an absent region would fault the
123	  // Program Buffer, unlike a tolerant CSR write. The simulator calls this from
124	  // its engine config (has_shared_cache + NDS_L2C_REG_BASE).
125	  void set_l2c(bool present, uint64_t base)
126	  {
127	    l2c_present_ = present;
128	    l2c_base_    = base;
129	  }
130	
131	  void resume(const hybrid_state_v1& state)
132	  {
133	    if (state.magic != HYBRID_STATE_MAGIC)
134	      throw std::runtime_error("ResumeDriver::resume: bad magic");
135	    if (state.version != HYBRID_STATE_VERSION)
136	      throw std::runtime_error("ResumeDriver::resume: unsupported version");
137	    // L6: only U(0)/S(1)/M(3) fit dcsr.prv; 2 is the reserved encoding.
138	    if (state.priv == 2 || state.priv > 3)
139	      throw std::runtime_error("ResumeDriver::resume: invalid privilege");
140	
141	    // dmactive must transition 0->1 in its own write before any other
142	    // DMCONTROL bit is honored (RISC-V Debug Spec).
143	    bus_.write(kDmcontrol, kDmcontrolDmactive);
144	    request_halt();
145	    poll_until_set(bus_, kDmstatus, kDmstatusAllhalted, "ResumeDriver halt");
146	
147	    // mstatus: enable FS / VS so the following FPR / V abstract writes are
148	    // accepted (FS or VS == Off disables the extension and the hart NACKs
149	    // the writes). The drained state.mstatus may legitimately carry FS or
150	    // VS at Off (e.g. an OS context-switched the regs away before the
151	    // trigger fired) -- gating the write on the drained field skips the
152	    // enable and silently NACKs every subsequent FPR / V-CSR write. Always
153	    // write mstatus when either extension is in scope; force-OR Initial
154	    // when the drained field is Off. This enable is local to the vsim
155	    // phase; the state.mstatus written to the handoff file is left
156	    // unmodified.
157	    if (state.flags & (HYBRID_FLAG_FP | HYBRID_FLAG_V)) {
158	      uint64_t enable_mstatus = state.mstatus;
159	      if ((state.flags & HYBRID_FLAG_FP) && (enable_mstatus & kMstatusFsMask) == 0)
160	        enable_mstatus |= kMstatusFsInitial;  // FS = Initial
161	      if ((state.flags & HYBRID_FLAG_V)  && (enable_mstatus & kMstatusVsMask) == 0)
162	        enable_mstatus |= kMstatusVsInitial;  // VS = Initial
163	      write_csr_abstract_or_pb(kCsrMstatus, enable_mstatus);
164	    }
165	
166	    // FPR restore (requires mstatus.FS enabled above): one abstract register
167	    // write per f-reg. Abstract-only by design, like every non-V register
168	    // block -- the Program Buffer is reserved for state the abstract command
169	    // space cannot reach (the V regfile, vtype/vl, L2C MMIO).
170	    if (state.flags & HYBRID_FLAG_FP) {
171	      // LG2: elide the whole FPR block when every f-reg already holds the
172	      // engine's reset value -- the reload would rewrite what is there.
173	      const bool fpr_equal = has_baseline_
174	        && std::memcmp(state.fpr, baseline_.fpr, sizeof state.fpr) == 0;
175	      if (fpr_equal) {
176	        baseline_skip_count_ += 32;
177	      } else {
178	        for (uint16_t i = 0; i < 32; ++i)
179	          write_64bit_register(regno_fpr(i), state.fpr[i]);
180	      }
181	      // L20: fcsr (frm + sticky fflags). Same FS gate as the FPRs; PB
182	      // fallback scratch x5 is overwritten by the GPR loop below.
183	      if (!baseline_skips(state.fcsr, baseline_.fcsr))
184	        write_csr_abstract_or_pb(kCsrFcsr, state.fcsr);
185	    }
186	
187	    // Tier-A V CSR restore (before GPRs: PB fallback uses x5 as scratch;
188	    // the GPR loop overwrites x5 afterward so state is preserved).
189	    if (state.flags & HYBRID_FLAG_V) {
190	      // V data regfile: reload v0..v31 from the shared scratch region via the
191	      // Program Buffer. Runs BEFORE the architectural V-CSR restore below
192	      // because the sweep's own vsetvl (e8/m8) clobbers vtype/vl/vstart, which
193	      // the restore then overwrites with the architectural values. The sweep
194	      // uses x5/x6/x7 as scratch (x7 is the group base pointer); the GPR loop
195	      // below restores all three. The scratch is vlenb-packed
196	      // (stage_v_to_scratch), so the sweep takes only the runtime vlenb.
197	      if (scratch_gpa_ == kVScratchGpaUnset)
198	        throw std::runtime_error(
199	          "ResumeDriver::resume: V state present but scratch GPA unset");
200	      // LG2: elide the reload sweep when every v-reg already holds the
201	      // engine's reset bytes.
202	      const bool v_data_equal = has_baseline_
203	        && std::memcmp(state.vreg, baseline_.vreg, sizeof state.vreg) == 0;
204	      if (v_data_equal)
205	        baseline_skip_count_ += 32;
206	      else
207	        pb_v_data_sweep(bus_, scratch_gpa_, state.vlenb, /*load=*/true);
208	
209	      // Tier-B: vtype+vl via vsetvl x0,x5,x6 in PB.
210	      // Direct csrrw to vtype sets vill; vl is read-only. Stage operands in
211	      // scratch GPRs x5(vl) and x6(vtype) then let vsetvl set both atomically.
212	      // x5/x6 are overwritten by the GPR loop below, so no leakage.
213	      // LG2 clobber rule: the data sweep's own vsetvl overwrote vtype/vl/
214	      // vstart, so baseline equality only proves this vsetvl redundant when
215	      // the sweep did NOT run.
216	      const bool vcfg_equal = v_data_equal && v_cfg_at_reset_
217	        && state.vl == baseline_.vl && state.vtype == baseline_.vtype;
218	      if (vcfg_equal) {
219	        ++baseline_skip_count_;  // the elided vsetvl exec
220	      } else {
221	        write_64bit_register(regno_gpr(5), state.vl);
222	        write_64bit_register(regno_gpr(6), state.vtype);
223	        const std::array<uint32_t, 1> pb_vsetvl = { encode_vsetvl(0, 5, 6) };
224	        exec_progbuf(bus_, std::span<const uint32_t>{pb_vsetvl});
225	      }
226	      // vstart must come AFTER vsetvl: vsetvl resets vstart to 0 -- so its
227	      // baseline skip is likewise only valid when no vsetvl executed.
228	      if (!(vcfg_equal && baseline_skips(state.vstart, baseline_.vstart)))
229	        write_csr_abstract_or_pb(kCsrVstart, state.vstart);
230	      if (!baseline_skips(state.vxsat, baseline_.vxsat))
231	        write_csr_abstract_or_pb(kCsrVxsat,  state.vxsat);
232	      if (!baseline_skips(state.vxrm, baseline_.vxrm))
233	        write_csr_abstract_or_pb(kCsrVxrm,   state.vxrm);
234	      if (!baseline_skips(state.vcsr, baseline_.vcsr))
235	        write_csr_abstract_or_pb(kCsrVcsr,   state.vcsr);
236	    }
237	
238	    // L6: dret resumes into dcsr.prv, which is M after the boot halt. For an
239	    // S/U-mode handoff, read-modify-write the prv field so the ROI executes
240	    // in the drained privilege; M-mode states skip the write (prv already 3).
241	    // Before the GPR loop: a PB fallback would clobber scratch x5.
242	    if (state.priv != 3) {
243	      // L2 slice: with PMP implemented and no matching entry, every S/U
244	      // access faults (priv spec v1.10) -- mirror the producer's PMP block
245	      // so the ROI can fetch at all. All pmpaddr before any pmpcfg (a locked
246	      // cfg discards later addr writes); odd pmpcfg CSRs do not exist on
247	      // RV64. Tolerant writes: entries beyond what the hart implements
248	      // mirror as no-ops. M-mode handoffs keep PMP pass-through-only (L2).
249	      for (uint16_t i = 0; i < HYBRID_PMP_ADDR_NUM; ++i)
250	        write_csr_tolerant(kCsrPmpaddr0 + i, state.pmpaddr[i]);
251	      for (uint16_t i = 0; i < HYBRID_PMP_CFG_NUM; i += 2)
252	        write_csr_tolerant(kCsrPmpcfg0 + i, state.pmpcfg[i]);
253	
254	      const uint64_t dcsr =
255	        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr");
256	      write_csr_abstract_or_pb(kCsrDcsr,
257	                               (dcsr & ~uint64_t{0x3}) | state.priv);
258	      // An M-only core WARL-pins dcsr.prv to 3; resuming anyway would
259	      // silently measure the ROI in the wrong privilege. Verify and abort.
260	      const uint64_t got =
261	        read_register_64(bus_, regno_csr(kCsrDcsr), "ResumeDriver dcsr verify")
262	        & 0x3u;
263	      if (got != state.priv)
264	        throw std::runtime_error(
265	          "ResumeDriver::resume: engine does not implement privilege level "
266	          + std::to_string(state.priv)
267	          + " (dcsr.prv pinned to " + std::to_string(got)
268	          + "); pick an S/U-capable engine");
269	    }
270	
271	    // Andes V5 + M-ext CSR restore (abstract-only, LG1-gated). See
272	    // restore_andes_m_ext.
273	    restore_andes_m_ext(state);
274	
275	    // v5: L2C MMIO config restore. Runs BEFORE the GPR loop (like the V sweep):
276	    // it stages an address + value into scratch GPRs x5/x6 and the GPR loop
277	    // below overwrites them with their architectural values, so the clobber is
278	    // safe. It CANNOT run after the loop, where every GPR already holds its
279	    // final value. See restore_l2c.
280	    restore_l2c(state);
281	
282	    // GPRs x1..x31 + DPC (after the V CSRs so the PB scratch GPRs the V block
283	    // staged -- x5/x6/x7 -- are safe to overwrite): one abstract register
284	    // write each (DATA0/DATA1 + Access-Register COMMAND), abstract-only by
285	    // design. x0 is hardwired zero and is skipped.
286	    for (uint16_t i = 1; i < 32; ++i)
287	      write_64bit_register(regno_gpr(i), state.gpr[i]);
288	    write_64bit_register(regno_csr(kCsrDpc), state.pc);
289	
290	    write_csr_tolerant_gated(kCsrMtvec, state.mtvec, baseline_.mtvec);
291	
292	    // L23: mscratch is the M-mode software scratch CSR -- a pure read/write
293	    // register with no hardware side effects, legal to use inside a trap-free
294	    // ROI. Restore it so a value stashed before the handoff survives into the
295	    // vsim phase.
296	    write_csr_tolerant_gated(kCsrMscratch, state.mscratch, baseline_.mscratch);
297	
298	    // L24: the writable M-mode trap/interrupt CSRs. In the trap-free,
299	    // interrupt-free ROI envelope these are ordinary read/write registers, so a
300	    // value stashed before the handoff must survive into the vsim phase (same
301	    // round-trip as mscratch). Tolerant writes: a WARL / read-only field (mip's
302	    // hardware-driven pending bits, or mtval on a core that hardwires it)
303	    // mirrors as a no-op. medeleg/mideleg/satp stay unrestored -- they are
304	    // S-mode CSRs the M-only default engine does not implement (L3/L4).
305	    write_csr_tolerant_gated(kCsrMepc,   state.mepc,   baseline_.mepc);
306	    write_csr_tolerant_gated(kCsrMcause, state.mcause, baseline_.mcause);
307	    write_csr_tolerant_gated(kCsrMtval,  state.mtval,  baseline_.mtval);
308	    write_csr_tolerant_gated(kCsrMie,    state.mie,    baseline_.mie);
309	    write_csr_tolerant_gated(kCsrMip,    state.mip,    baseline_.mip);
310	
311	    // Andes cache fix: restore the machine setup CSRs crt0 wrote at boot. The
312	    // functional engine ran crt0 (where `csrw mcache_ctl` enables the L1 I/D
313	    // caches) but has no cache model, so without this the cycle engine resumes
314	    // at the ROI with caches at their reset default -- DISABLED -- and the
315	    // whole measured window runs uncached, inflating it severalfold. Tolerant
316	    // writes: an engine without these custom CSRs (e.g. non-Andes) mirrors the
317	    // write as a no-op, and a drained 0 (caches were off) restores the reset
318	    // state, so this is always safe to issue.
319	    if (wm_live(state, HYBRID_WM_MCACHE_CTL))
320	      write_csr_tolerant_gated(kCsrMcacheCtl, state.mcache_ctl,
321	                               baseline_.mcache_ctl);
322	    if (wm_live(state, HYBRID_WM_MMISC_CTL))
323	      write_csr_tolerant_gated(kCsrMmiscCtl,  state.mmisc_ctl,
324	                               baseline_.mmisc_ctl);
325	
326	    // F-T2.4: restore mcycle/minstret so the vsim phase continues counting
327	    // from QEMU1's drain value. Without this, vsim's local counter starts
328	    // at zero, so the drained mcycle delta (vsim minus QEMU 1) would no
329	    // longer measure the ROI. PB fallback uses x5 as scratch; safe to
330	    // overwrite here as the GPR loop already ran.
331	    write_csr_abstract_or_pb(kCsrMcycle,   state.mcycle);
332	    write_csr_abstract_or_pb(kCsrMinstret, state.minstret);
333	
334	    clear_cmderr_if_set();
335	    request_resume();
336	    poll_until_set(bus_, kDmstatus, kDmstatusAllresumeack,
337	                   "ResumeDriver resume");
338	  }
