340	private:
341	  void request_halt()
342	  {
343	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolHaltreq);
344	  }
345	
346	  void request_resume()
347	  {
348	    bus_.write(kDmcontrol, kDmcontrolDmactive | kDmcontrolResumereq);
349	  }
350	
351	  void write_64bit_register(uint16_t regno, uint64_t value)
352	  {
353	    write_register_abstract(bus_, regno, value);
354	  }
355	
356	  // v5: write back the WRITABLE boot-static L2C config registers via
357	  // Program-Buffer word stores. The L2C block is MMIO, not a CSR, so each write
358	  // is `sw x5, 0(x6)` with the register address staged in x6 and the value (low
359	  // word) in x5. Restores ONLY the config registers the ROI can hold as plain
360	  // state: Control (CEN/prefetch/ECC/RAM timing), HPM Control, Way Allocation
361	  // Masks. The read-only Configuration Register, the side-effecting CCTL command
362	  // registers (writing one re-issues an L2 cache op), and the write-1-clear
363	  // error registers are captured in the record but NEVER written back.
364	  //
365	  // Hard-gated on the engine having an L2C (l2c_present_): a store to an absent
366	  // L2C region faults the Program Buffer, so unlike a tolerant CSR write this
367	  // must issue nothing on a core without an L2C. x5/x6 are safe scratch here --
368	  // the caller runs this before the GPR loop, which overwrites both.
369	  void restore_l2c(const hybrid_state_v1& state)
370	  {
371	    if (!(state.flags & HYBRID_FLAG_L2C)) return;
372	    if (!l2c_present_) return;
373	
374	    pb_store_l2c_reg(HYBRID_L2C_OFF_CONTROL,
375	                     state.l2c.reg[HYBRID_L2C_OFF_CONTROL / 8]);
376	    pb_store_l2c_reg(HYBRID_L2C_OFF_HPM_CTL0,
377	                     state.l2c.reg[HYBRID_L2C_OFF_HPM_CTL0 / 8]);
378	    for (uint32_t i = 0; i < HYBRID_L2C_WAYMASK_NUM; ++i) {
379	      const uint32_t off = HYBRID_L2C_OFF_WAYMASK0 + i * 8u;
380	      pb_store_l2c_reg(off, state.l2c.reg[off / 8]);
381	    }
382	  }
383	
384	  // One L2C register store: stage the MMIO address in x6 and the value's low
385	  // word in x5, then execute `sw x5, 0(x6)` in the Program Buffer. Word store
386	  // per DS220 11.8.3 (single transfer, access size < 8 bytes); all documented
387	  // L2C control bits live in the low 32.
388	  void pb_store_l2c_reg(uint32_t offset, uint64_t value)
389	  {
390	    write_register_abstract(bus_, regno_gpr(6), l2c_base_ + offset);
391	    write_register_abstract(bus_, regno_gpr(5), value & 0xffffffffu);
392	    const std::array<uint32_t, 1> pb = { encode_sw(5, 6, 0) };
393	    exec_progbuf(bus_, std::span<const uint32_t>{pb});
394	  }
395	
396	  // Andes V5 + M-ext CSR restore: one caps-gated abstract write per CSR
397	  // (pmaaddr before pmacfg, mirroring the PMP restore ordering), each gated by
398	  // the LG1 reset baseline. Abstract-only by design -- a batched Program-Buffer
399	  // sweep can't tolerate a cmderr on one CSR without corrupting the rest of the
400	  // batch (a WARL/read-only CSR faults the whole group mid-sweep), whereas the
401	  // per-CSR abstract path tolerates a single failure and moves on.
402	  void restore_andes_m_ext(const hybrid_state_v1& state)
403	  {
404	    const bool andes = state.flags & HYBRID_FLAG_ANDES;
405	    const bool mext  = state.flags & HYBRID_FLAG_M_EXT;
406	    if (!andes && !mext) return;
407	
408	    // Each write is double-gated: caps (the ENGINE implements the CSR) and the
409	    // v6 write-mask (the PRODUCER's guest actually wrote it -- wm_live).
410	    if (andes) {
411	#define X(field, addr, name)                                                  \
412	  if (caps_.supports_csr(addr)                                                \
413	      && wm_live(state, HYBRID_WM_ANDES_BASE + HYBRID_WM_ANDES_IDX_##field))  \
414	    write_csr_tolerant_gated(addr, state.andes.field, baseline_.andes.field);
415	      HYBRID_ANDES_CSR_LIST(X)
416	#undef X
417	      for (uint16_t i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
418	        if (caps_.supports_csr(HYBRID_PMA_ADDR0_CSR + i)
419	            && wm_live(state, HYBRID_WM_PMAADDR_BASE + i))
420	          write_csr_tolerant_gated(HYBRID_PMA_ADDR0_CSR + i,
421	                                   state.andes.pmaaddr[i],
422	                                   baseline_.andes.pmaaddr[i]);
423	      for (uint16_t i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
424	        if (caps_.supports_csr(HYBRID_PMA_CFG0_CSR + 2 * i)
425	            && wm_live(state, HYBRID_WM_PMACFG_BASE + i))
426	          write_csr_tolerant_gated(HYBRID_PMA_CFG0_CSR + 2 * i,
427	                                   state.andes.pmacfg[i],
428	                                   baseline_.andes.pmacfg[i]);
429	    }
430	    if (mext) {
431	#define X(field, addr, name)                                                  \
432	  if (caps_.supports_csr(addr)                                                \
433	      && wm_live(state, HYBRID_WM_M_EXT_BASE + HYBRID_WM_M_EXT_IDX_##field))  \
434	    write_csr_tolerant_gated(addr, state.m_ext.field, baseline_.m_ext.field);
435	      HYBRID_M_EXT_CSR_LIST(X)
436	#undef X
437	    }
438	  }
439	
440	  // Abstract-first CSR write with Program Buffer fallback.
441	  // Tries an abstract register write; if the DM signals cmderr, clears it,
442	  // stages the value in scratch_gpr via abstract GPR write, then executes a
443	  // one-instruction PB (`csrrw x0, csr, scratch_gpr`).  scratch_gpr defaults
444	  // to x5 (t0) which the GPR restore loop overwrites later.
445	  void write_csr_abstract_or_pb(uint16_t csr, uint64_t value,
446	                                 uint8_t scratch_gpr = 5)
447	  {
448	    write_64bit_register(regno_csr(csr), value);
449	    if ((bus_.read(kAbstractcs) & kAbstractcsCmderrMask) == 0u) return;
450	    bus_.write(kAbstractcs, kAbstractcsCmderrMask);  // W1C: clear sticky error
451	    write_64bit_register(regno_gpr(scratch_gpr), value);
452	    const std::array<uint32_t, 1> pb = { encode_csrrw(0, csr, scratch_gpr) };
453	    exec_progbuf(bus_, std::span<const uint32_t>{pb});
454	  }
455	
456	  // Write a CSR-addressable register and clear any cmderr the DM raised.
457	  // Used for CSRs whose abstract-access support may be implementation
458	  // dependent; a missing CSR mirrors as a no-op rather than blocking the
459	  // remaining writes.
460	  void write_csr_tolerant(uint16_t csr, uint64_t value)
461	  {
462	    write_64bit_register(regno_csr(csr), value);
463	    clear_cmderr_if_set();
464	  }
465	
466	  // v6: true when the handoff says this mask-governed CSR is live -- the
467	  // producer's guest actually wrote it, or the producer carried no mask at all
468	  // (pre-v6 file: restore-everything fallback). An untouched CSR is skipped so
469	  // the engine keeps its OWN reset value: the drained value is only the
470	  // producer's reset default, which may legitimately differ from this RTL's
471	  // (msp_bound all-ones vs 0, milmb.IEN 0 vs 1; see hybrid/write_mask.h).
472	  static auto wm_live(const hybrid_state_v1& state, int slot) -> bool
473	  {
474	    if (!(state.flags & HYBRID_FLAG_WRITE_MASK)) return true;
475	    return hybrid_wm_test(state.write_mask, static_cast<unsigned>(slot)) != 0;
476	  }
477	
478	  // LG1: true (and counted) when the reset baseline marks this write a no-op.
479	  auto baseline_skips(uint64_t value, uint64_t reset_value) -> bool
480	  {
481	    if (!has_baseline_ || value != reset_value) return false;
482	    ++baseline_skip_count_;
483	    return true;
484	  }
485	
486	  // Tolerant CSR write elided when the value already equals the engine's
487	  // reset value (reset_value is only meaningful when the baseline is set;
488	  // baseline_ is zero-initialized otherwise and baseline_skips ignores it).
489	  void write_csr_tolerant_gated(uint16_t csr, uint64_t value,
490	                                uint64_t reset_value)
491	  {
492	    if (baseline_skips(value, reset_value)) return;
493	    write_csr_tolerant(csr, value);
494	  }
495	
496	  // abstractcs.cmderr is sticky per the Debug Spec - a subsequent command
497	  // is rejected until the bits are W1C-cleared. We tolerate per-register
498	  // failures (e.g. unimplemented FPR/CSR Abstract access) by clearing the
499	  // error before resuming so the hart isn't left in a stuck state.
500	  // B17: record the last observed non-zero cmderr and a clear count so a
501	  // partially-broken restore is observable via the public accessors
502	  // instead of silently swallowed.
503	  void clear_cmderr_if_set()
504	  {
505	    const auto status = bus_.read(kAbstractcs);
506	    const auto code = (status & kAbstractcsCmderrMask) >> 8;
507	    if (code != 0u) {
508	      last_observed_cmderr_ = code;
509	      ++cmderr_clear_count_;
510	      bus_.write(kAbstractcs, kAbstractcsCmderrMask);
511	    }
512	  }
513	
514	  DmiBus& bus_;
515	  uint64_t scratch_gpa_ = kVScratchGpaUnset;  // L26: V transport page GPA
516	  AndesCaps caps_ = AndesCaps::all();         // target core's Andes-CSR support
517	  bool l2c_present_ = false;                  // v5: engine has an L2C (set_l2c)
518	  uint64_t l2c_base_ = 0;                     // v5: L2C MMIO register base
519	  hybrid_state_v1 baseline_{};                // LG1: engine reset-state drain
520	  bool has_baseline_ = false;                 // baseline_ valid only when set
521	  bool v_cfg_at_reset_ = true;                // false: capture clobbered vcfg
522	  uint64_t baseline_skip_count_ = 0;          // LG1: elided tolerant writes
523	  uint32_t last_observed_cmderr_ = 0;
524	  uint64_t cmderr_clear_count_   = 0;
525	
526	public:
527	  // B17: diagnostic side channel. Non-zero last_observed_cmderr() means
528	  // at least one abstract write tripped a sticky cmderr the restore
529	  // tolerated by clearing. cmderr_clear_count() is the total number of
530	  // such clears across all calls into clear_cmderr_if_set() this run.
531	  auto last_observed_cmderr() const -> uint32_t { return last_observed_cmderr_; }
532	  auto cmderr_clear_count() const -> uint64_t   { return cmderr_clear_count_; }
533	};
534	
535	// Read a 64-bit hart register (GPR / FPR / CSR by abstract regno) over DMI
536	// via an Abstract Command. Halts-and-reads contract: caller must have the
537	// hart in the halted state. Shared with StateDrain (drain at exit). If
538	// abstractcs.cmderr goes sticky after the command, the helper clears it and
539	// reports nullopt rather than blocking the caller -- a missing CSR mirrors as
540	// absent instead of corrupting the adjacent field.
541	inline auto read_register_64_checked(DmiBus& bus, uint16_t regno,
542	                                     const char* poll_label
543	                                       = "read_register_64")
544	  -> std::optional<uint64_t>
545	{
546	  using RD = ResumeDriver;
547	  bus.write(RD::kCommand,
548	            access_register_command(regno, AarSize::Bits64, /*write=*/false));
549	  poll_until_clear(bus, RD::kAbstractcs, RD::kAbstractcsBusy, poll_label);
550	  const auto status = bus.read(RD::kAbstractcs);
551	  if ((status & RD::kAbstractcsCmderrMask) != 0u) {
552	    bus.write(RD::kAbstractcs, RD::kAbstractcsCmderrMask);
553	    return std::nullopt;
554	  }
555	  const uint64_t lo = bus.read(RD::kData0);
556	  const uint64_t hi = bus.read(RD::kData1);
557	  return lo | (hi << 32);
558	}
559	
560	inline auto read_register_64(DmiBus& bus, uint16_t regno,
561	                             const char* poll_label = "read_register_64")
562	  -> uint64_t
563	{
564	  return read_register_64_checked(bus, regno, poll_label).value_or(0u);
565	}
