1	// StateDrain halts the hart via the Debug Module and populates a
2	// hybrid_state_v1 with the architectural register file. Reuses
3	// ResumeDriver's DM register constants and DmiBus interface.
4	
5	#pragma once
6	
7	#include "hybrid/abstract_command.hpp"
8	#include "hybrid/andes_caps.hpp"
9	#include "hybrid/dmi_poll.hpp"
10	#include "hybrid/resume_driver.hpp"
11	#include "hybrid/state_abi.h"
12	#include "hybrid/v_regfile_xfer.hpp"
13	
14	#include <array>
15	#include <cstdint>
16	#include <span>
17	
18	namespace hybrid
19	{
20	
21	class StateDrain
22	{
23	public:
24	  using RD = ResumeDriver;
25	
26	  // scratch_gpa: the GUEST address of the V-register transport page (L26: the
27	  // mmap's top page, v_scratch_gpa(ram_base, ram_size)). Defaults to the unset
28	  // sentinel; only the V dump sweep consults it. The simulator passes the real
29	  // value from platform.main_memory.
30	  explicit StateDrain(DmiBus& bus, uint64_t scratch_gpa = kVScratchGpaUnset,
31	                      AndesCaps caps = AndesCaps::all())
32	      : bus_{bus}, scratch_gpa_{scratch_gpa}, caps_{caps}
33	  {}
34	
35	  // v5: declare whether the target engine has an L2 cache controller, and its
36	  // MMIO register base (dual of ResumeDriver::set_l2c). Off by default so an
37	  // engine without an L2C reads nothing back -- a load from an absent region
38	  // would fault the Program Buffer. The simulator calls this from its engine
39	  // config (has_shared_cache + NDS_L2C_REG_BASE).
40	  void set_l2c(bool present, uint64_t base)
41	  {
42	    l2c_present_ = present;
43	    l2c_base_    = base;
44	  }
45	
46	  // Drain x1..x31 + PC. FP/CSR/V slots remain zero; merge them in via
47	  // drain_with_passthrough when the QEMU 1 snapshot is available.
48	  auto drain() -> hybrid_state_v1
49	  {
50	    hybrid_state_v1 state{};
51	    state.magic   = HYBRID_STATE_MAGIC;
52	    state.version = HYBRID_STATE_VERSION;
53	    state.flags   = HYBRID_FLAG_RV64;
54	    halt_and_capture_pc_priv(state);
55	
56	    for (uint16_t i = 1; i < 32; ++i)
57	      state.gpr[i] = read_register_64(bus_, regno_gpr(i), "StateDrain GPR");
58	
59	    return state;
60	  }
61	
62	  // Returns the input snapshot with x1..x31 and PC overwritten by a fresh
63	  // DM read. When HYBRID_FLAG_FP is set, also freshly reads f0..f31 + fcsr
64	  // (L20) so post-vsim FP modifications are captured (otherwise the stale
65	  // QEMU 1 snapshot leaks into the drained state). When HYBRID_FLAG_V is set,
66	  // also freshly reads the six V CSRs (vstart/vxsat/vxrm/vcsr/vtype/vl); vlenb
67	  // and vreg remain pass-through (read-only / too large for DM). L23 mscratch
68	  // and the L24 trap/interrupt CSRs round-trip too (ResumeDriver restores
69	  // them). The Andes block, the M-ext CSRs, and the writable L2C config
70	  // registers round-trip too.
71	  // mcycle/minstret are always refreshed (F-T2.4): the vsim phase's
72	  // contribution would otherwise be discarded as the passthrough preserves
73	  // QEMU1's pre-handoff value.
74	  auto drain_with_passthrough(const hybrid_state_v1& input) -> hybrid_state_v1
75	  {
76	    auto state = input;
77	    halt_and_capture_pc_priv(state);  // L6: pc + privilege at the exit halt
78	
79	    // GPRs/FPRs: one abstract register read each. Abstract-only by design,
80	    // like the resume side -- the Program Buffer is reserved for state the
81	    // abstract command space cannot reach (the V regfile, vtype+vl, the L2C
82	    // MMIO window).
83	    for (uint16_t i = 1; i < 32; ++i)
84	      state.gpr[i] = read_register_64(bus_, regno_gpr(i), "StateDrain GPR");
85	
86	    if (input.flags & HYBRID_FLAG_FP) {
87	      for (uint16_t i = 0; i < 32; ++i)
88	        state.fpr[i] = read_register_64(bus_, regno_fpr(i), "StateDrain FPR");
89	      // L20: fcsr (frm + sticky fflags) accumulated by the vsim phase.
90	      state.fcsr = read_register_64(bus_, regno_csr(RD::kCsrFcsr));
91	    }
92	
93	    if (input.flags & HYBRID_FLAG_V) {
94	      state.vstart = read_register_64(bus_, regno_csr(RD::kCsrVstart));
95	      state.vxsat  = read_register_64(bus_, regno_csr(RD::kCsrVxsat));
96	      state.vxrm   = read_register_64(bus_, regno_csr(RD::kCsrVxrm));
97	      state.vcsr   = read_register_64(bus_, regno_csr(RD::kCsrVcsr));
98	      state.vtype  = read_register_64(bus_, regno_csr(RD::kCsrVtype));
99	      state.vl     = read_register_64(bus_, regno_csr(RD::kCsrVl));
100	    }
101	
102	    // L23: mscratch round-trips now (ResumeDriver restores it), so re-read it
103	    // from the hart -- otherwise an in-ROI write to the software scratch CSR is
104	    // dropped and the stale QEMU1 value passes through into the drained state.
105	    state.mscratch = read_register_64(bus_, regno_csr(RD::kCsrMscratch));
106	
107	    // L24: the writable M-mode trap/interrupt CSRs round-trip too (ResumeDriver
108	    // restores them), so re-read them -- an in-ROI write must reach the drained
109	    // state instead of the stale QEMU1 passthrough value.
110	    state.mepc   = read_register_64(bus_, regno_csr(RD::kCsrMepc));
111	    state.mcause = read_register_64(bus_, regno_csr(RD::kCsrMcause));
112	    state.mtval  = read_register_64(bus_, regno_csr(RD::kCsrMtval));
113	    state.mie    = read_register_64(bus_, regno_csr(RD::kCsrMie));
114	    state.mip    = read_register_64(bus_, regno_csr(RD::kCsrMip));
115	
116	    state.mcycle   = read_register_64(bus_, regno_csr(RD::kCsrMcycle));
117	    state.minstret = read_register_64(bus_, regno_csr(RD::kCsrMinstret));
118	
119	    // Andes V5 + M-ext CSR block (v3/v4): re-read the transported CSRs so an
120	    // in-ROI write reaches the drained state instead of the stale QEMU1
121	    // passthrough (same round-trip as mscratch). One caps-gated abstract read
122	    // per CSR. See drain_andes_m_ext.
123	    drain_andes_m_ext(state);
124	
125	    // v5: re-read the writable L2C config registers (the ones ResumeDriver
126	    // restored) so the --verify oracle sees the round-tripped values instead of
127	    // the stale QEMU1 passthrough. The ROI is trap-free and does not touch L2C
128	    // config, so these must match the producer. Clobbers x5/x6 -- safe here, the
129	    // GPRs are already captured above and the hart is terminal. See drain_l2c.
130	    drain_l2c(state);
131	
132	    // V data regfile: dump v0..v31 to the shared scratch region via the
133	    // Program Buffer LAST -- after every architectural read above -- so the
134	    // sweep's clobbers (vtype/vl/vstart, x5/x6/x7) and its counter increments
135	    // cannot corrupt the values already captured. The simulator's
136	    // read_v_from_scratch then lifts the scratch bytes into state.vreg[].
137	    if (input.flags & HYBRID_FLAG_V)
138	      dump_v_to_scratch(input.vlenb);
139	
140	    return state;
141	  }
142	
143	  // #1 (drain-minimal): refresh only mcycle/minstret from the hart and pass
144	  // every other field through from the QEMU1 snapshot. Used when --verify is
145	  // off: the driver then consumes only the vsim mcycle delta, so the full
146	  // register-file readback drain_with_passthrough performs (~190 DMI abstract
147	  // commands -- f0..f31, the V dump sweep, the Andes/M-ext blocks, ...) is pure
148	  // wasted wall-clock. The hart is left halted, identical to the full drain, so
149	  // the caller's file-write + exit path is unchanged.
150	  auto drain_counters_only(const hybrid_state_v1& input) -> hybrid_state_v1
151	  {
152	    halt("StateDrain halt (minimal)");
153	
154	    auto state     = input;
155	    state.mcycle   = read_register_64(bus_, regno_csr(RD::kCsrMcycle),
156	                                      "StateDrain mcycle");
157	    state.minstret = read_register_64(bus_, regno_csr(RD::kCsrMinstret),
158	                                      "StateDrain minstret");
159	    return state;
160	  }
161	
162	private:
163	  // Debug-Module halt-and-wait, shared by drain() and drain_counters_only():
164	  // dmactive must transition 0->1 in its own write before haltreq is honored
165	  // (RISC-V Debug Spec), then wait for allhalted. `ctx` labels the poll.
166	  void halt(const char* ctx)
167	  {
168	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
169	    bus_.write(RD::kDmcontrol, RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
170	    poll_until_set(bus_, RD::kDmstatus, RD::kDmstatusAllhalted, ctx);
171	  }
172	
173	  // Halt the hart and capture the two control fields every drain path needs:
174	  // privilege (dcsr.prv, L6) and PC (dpc). Header fields and the register
175	  // blocks are filled by the caller, so drain() and drain_with_passthrough
176	  // share one halt + prologue.
177	  void halt_and_capture_pc_priv(hybrid_state_v1& state)
178	  {
179	    halt("StateDrain halt");
180	    state.priv = read_register_64(bus_, regno_csr(RD::kCsrDcsr),
181	                                  "StateDrain DCSR") & 0x3u;
182	    state.pc = read_register_64(bus_, regno_csr(RD::kCsrDpc), "StateDrain DPC");
183	  }
184	
185	  // Andes V5 + M-ext CSR drain: one caps-gated abstract read per CSR into
186	  // state. Abstract-only by design, same caps gate + canonical order as the
187	  // ResumeDriver restore.
188	  void drain_andes_m_ext(hybrid_state_v1& state)
189	  {
190	    const bool andes = state.flags & HYBRID_FLAG_ANDES;
191	    const bool mext  = state.flags & HYBRID_FLAG_M_EXT;
192	    if (!andes && !mext) return;
193	
194	    if (andes) {
195	#define X(field, addr, name) \
196	  if (caps_.supports_csr(addr)) \
197	    state.andes.field = read_register_64(bus_, regno_csr(addr));
198	      HYBRID_ANDES_CSR_LIST(X)
199	#undef X
200	      for (int i = 0; i < HYBRID_PMA_CFG_NUM; ++i)
201	        if (caps_.supports_csr(HYBRID_PMA_CFG0_CSR + 2 * i))
202	          state.andes.pmacfg[i] =
203	            read_register_64(bus_, regno_csr(HYBRID_PMA_CFG0_CSR + 2 * i));
204	      for (int i = 0; i < HYBRID_PMA_ADDR_NUM; ++i)
205	        if (caps_.supports_csr(HYBRID_PMA_ADDR0_CSR + i))
206	          state.andes.pmaaddr[i] =
207	            read_register_64(bus_, regno_csr(HYBRID_PMA_ADDR0_CSR + i));
208	    }
209	    if (mext) {
210	#define X(field, addr, name) \
211	  if (caps_.supports_csr(addr)) \
212	    state.m_ext.field = read_register_64(bus_, regno_csr(addr));
213	      HYBRID_M_EXT_CSR_LIST(X)
214	#undef X
215	    }
216	  }
217	
218	  // V data dump sweep: vse8.v v0..v31 from the regfile into the scratch page.
219	  // L26: guards on the configured scratch GPA so a V drain never stores to a
220	  // bogus address (mirror of ResumeDriver's reload-sweep guard).
221	  void dump_v_to_scratch(uint64_t vlenb)
222	  {
223	    if (scratch_gpa_ == kVScratchGpaUnset)
224	      throw std::runtime_error(
225	        "StateDrain: V state present but scratch GPA unset");
226	    pb_v_data_sweep(bus_, scratch_gpa_, vlenb, /*load=*/false);
227	  }
228	
229	  // v5: re-read the writable L2C config registers via Program-Buffer word loads,
230	  // the dual of ResumeDriver::restore_l2c. Reads back ONLY the registers the
231	  // resume side restored -- Control, HPM Control, Way Allocation Masks -- so the
232	  // --verify oracle compares round-tripped values. Hard-gated on the engine
233	  // having an L2C (a load from an absent region faults the Program Buffer).
234	  void drain_l2c(hybrid_state_v1& state)
235	  {
236	    if (!(state.flags & HYBRID_FLAG_L2C)) return;
237	    if (!l2c_present_) return;
238	
239	    state.l2c.reg[HYBRID_L2C_OFF_CONTROL / 8]  = pb_load_l2c_reg(HYBRID_L2C_OFF_CONTROL);
240	    state.l2c.reg[HYBRID_L2C_OFF_HPM_CTL0 / 8] = pb_load_l2c_reg(HYBRID_L2C_OFF_HPM_CTL0);
241	    for (uint32_t i = 0; i < HYBRID_L2C_WAYMASK_NUM; ++i) {
242	      const uint32_t off = HYBRID_L2C_OFF_WAYMASK0 + i * 8u;
243	      state.l2c.reg[off / 8] = pb_load_l2c_reg(off);
244	    }
245	  }
246	
247	  // One L2C register read-back: stage the MMIO address in x6, execute
248	  // `lwu x5, 0(x6)` in the Program Buffer, then read x5. lwu (zero-extend) so a
249	  // 32-bit register value does not sign-pollute the drained u64. Word access
250	  // per DS220 11.8.3 (< 8 bytes).
251	  auto pb_load_l2c_reg(uint32_t offset) -> uint64_t
252	  {
253	    write_register_abstract(bus_, regno_gpr(6), l2c_base_ + offset);
254	    const std::array<uint32_t, 1> pb = { encode_lwu(5, 6, 0) };
255	    exec_progbuf(bus_, std::span<const uint32_t>{pb});
256	    return read_register_64(bus_, regno_gpr(5), "StateDrain L2C reg");
257	  }
258	
259	  DmiBus& bus_;
260	  uint64_t scratch_gpa_ = kVScratchGpaUnset;  // L26: V transport page GPA
261	  AndesCaps caps_ = AndesCaps::all();         // target core's Andes-CSR support
262	  bool l2c_present_     = false;              // v5: engine has an L2C (set_l2c)
263	  uint64_t l2c_base_    = 0;                  // v5: L2C MMIO register base
264	};
