220	  // Caller invariant: the CPU must already be out of reset.
221	  //
222	  // baseline_cache (LG3): path to this (engine build, ELF)'s reset-state
223	  // baseline; empty disables the liveness gate (transport-everything). On a
224	  // cache miss the baseline is captured HERE: the hart is freshly reset and
225	  // the capture drain halts it exactly where resume() would, so the drained
226	  // values ARE what the gate must compare restores against. Capture runs
227	  // BEFORE the scratch stagings below -- its drain sweeps dump reset
228	  // registers through the same scratch page the stagings fill.
229	  void apply_resume_from_qemu(const std::string& path,
230	                              const std::string& baseline_cache = {})
231	  {
232	    hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width, PLATFORM::dmi_data_width>
233	      bus{platform.dmi, platform.clk.period()};
234	    hybrid_input_state_ = hybrid::load_state(path);
235	
236	    std::optional<hybrid_state_v1> baseline{};
237	    bool baseline_captured = false;
238	    if (!baseline_cache.empty()) {
239	      baseline = hybrid::try_load_reset_baseline(baseline_cache);
240	      // Stale-shape insurance: a cache whose flags/vlenb no longer cover the
241	      // incoming state was captured under a different engine/QEMU pairing.
242	      if (baseline
243	          && ((baseline->flags & hybrid_input_state_->flags)
244	                != hybrid_input_state_->flags
245	              || baseline->vlenb != hybrid_input_state_->vlenb))
246	        baseline.reset();
247	      if (!baseline) {
248	        baseline = capture_reset_baseline(bus, *hybrid_input_state_);
249	        baseline_captured = true;
250	        if (!hybrid::save_reset_baseline(baseline_cache, *baseline))
251	          spdlog::warn("hybrid: cannot save reset baseline to {}",
252	                       baseline_cache);
253	      }
254	      spdlog::info("hybrid: reset baseline {} ({})",
255	                   baseline_captured
256	                     ? "captured -- one-time cost per engine build + ELF"
257	                     : "cache hit",
258	                   baseline_cache);
259	    }
260	
261	    // Stage V-register bytes into the fixed scratch region of RAM BEFORE
262	    // resume: ResumeDriver's Program-Buffer reload sweep issues vle8.v from
263	    // this region to repopulate v0..v31, so the bytes must be in place first.
264	    // Best-effort: mismatched RAM layouts throw, which is louder than silently
265	    // dropping V state.
266	    if ((hybrid_input_state_->flags & HYBRID_FLAG_V) != 0u) {
267	      hybrid::stage_v_to_scratch(*hybrid_input_state_,
268	                                 platform.main_memory.data);
269	    }
270	    // GPR/FPR/CSR transport is Abstract-Command-only in BOTH directions (never
271	    // Program Buffer): a csrrw to a caps-supported but read-only / WARL-illegal
272	    // CSR raises cmderr, and the abstract path's per-CSR clear_cmderr tolerates
273	    // that single failure and moves on -- a batched PB sweep could not. The
274	    // Program Buffer carries only what abstract commands cannot reach: the V
275	    // data sweep, the Tier-B vsetvl, and the L2C MMIO window.
276	    const auto caps = active_caps();
277	    hybrid::ResumeDriver driver(bus, v_scratch_gpa(), caps);
278	    driver.set_l2c(l2c_present(), l2c_base());  // v5: restore L2C config if present
279	    // LG3: on a capture run the capture drain's V dump sweep clobbered
280	    // vtype/vl/vstart, so the vsetvl elision is only valid on cache hits.
281	    if (baseline)
282	      driver.set_reset_baseline(*baseline,
283	                                /*v_cfg_at_reset=*/!baseline_captured);
284	    std::size_t andes_mext_csrs = 0;
285	    hybrid::for_each_transport_csr(*hybrid_input_state_, caps,
286	      [&](uint16_t, const uint64_t&) { ++andes_mext_csrs; });
287	    const auto resume_t0 = sc_core::sc_time_stamp();
288	    const auto wall_t0 = std::chrono::steady_clock::now();
289	    driver.resume(*hybrid_input_state_);
290	    const auto wall_ms = std::chrono::duration_cast<std::chrono::milliseconds>(
291	      std::chrono::steady_clock::now() - wall_t0).count();
292	    const auto resume_cycles = static_cast<uint64_t>(
293	      (sc_core::sc_time_stamp() - resume_t0) / platform.clk.period());
294	    spdlog::info("hybrid: resume={} cycles ({} ms wall), restore path="
295	                 "abstract, andes+m-ext csrs={}",
296	                 resume_cycles, wall_ms, andes_mext_csrs);
297	    if (baseline)
298	      spdlog::info("hybrid: liveness gate elided {} register restores",
299	                   driver.baseline_skip_count());
300	  }
301	
302	  // F3: standalone CSR existence + reset-value probe. Halts the freshly-reset
303	  // hart via DMI and checked-reads each address -- cmderr (an unimplemented
304	  // CSR) surfaces as nullopt. No QEMU state, no run(): the read values ARE the
305	  // architectural reset state. Emitted by `--probe`, consumed by andesim's
306	  // gen_manifest.py to MEASURE the implemented set + reset values instead of
307	  // hand-tracing RTL params. The caller must load a (spin) ELF first so the
308	  // reset vector is mapped -- the hart fetches a couple instructions from it
309	  // before the DMI halt takes effect (same window capture_reset_baseline uses).
310	  auto probe_csrs(const std::vector<uint16_t>& addrs)
311	    -> std::vector<std::pair<uint16_t, std::optional<uint64_t>>>
312	  {
313	    using RD = hybrid::ResumeDriver;
314	    hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width, PLATFORM::dmi_data_width>
315	      bus{platform.dmi, platform.clk.period()};
316	    bus.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
317	    bus.write(RD::kDmcontrol, RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
318	    hybrid::poll_until_set(bus, RD::kDmstatus, RD::kDmstatusAllhalted,
319	                           "csr-probe halt");
320	    // At reset mstatus.FS/VS are Off, so FP/V CSR reads raise illegal-insn
321	    // (cmderr) and would mis-probe as absent. Enable them (WARL no-op on an
322	    // engine without FP/V), exactly like capture_reset_baseline before its
323	    // FP/V reads. mstatus's own probed value is thus FS/VS-perturbed -- a known
324	    // artifact (mstatus is a base always-transported, verify-excluded CSR).
325	    {
326	      const uint64_t mstatus = hybrid::read_register_64(
327	        bus, hybrid::regno_csr(RD::kCsrMstatus), "csr-probe mstatus");
328	      uint64_t enable = mstatus;
329	      if ((enable & RD::kMstatusFsMask) == 0) enable |= RD::kMstatusFsInitial;
330	      if ((enable & RD::kMstatusVsMask) == 0) enable |= RD::kMstatusVsInitial;
331	      if (enable != mstatus)
332	        hybrid::write_register_abstract(
333	          bus, hybrid::regno_csr(RD::kCsrMstatus), enable);
334	    }
335	    std::vector<std::pair<uint16_t, std::optional<uint64_t>>> out;
336	    out.reserve(addrs.size());
337	    for (const uint16_t a: addrs)
338	      out.emplace_back(a, hybrid::read_register_64_checked(
339	                            bus, hybrid::regno_csr(a), "csr-probe"));
340	    return out;
341	  }
342	
343	  // Enables the vsim->QEMU handoff drain. After this is set, run() watches
344	  // committed PCs and on retire of the `slti x0, x0, 0x5A1` exit marker drains
345	  // architectural state to `state_out_path` and returns kExitHandoffToQemu.
346	  //
347	  // When `exit_pc` is set, the trigger is populated by `add_pc_hit` (PC
348	  // mode) and the ELF scan is skipped: the binary need not contain a marker
349	  // HINT. Marker mode and PC mode are mutually exclusive on a single run --
350	  // callers pass exactly one form.
351	  void enable_hybrid_handoff(const std::string& elf_path,
352	                             const std::string& state_out_path,
353	                             std::optional<uint64_t> exit_pc = std::nullopt,
354	                             bool drain_minimal = false)
355	  {
356	    hybrid::CsrTrigger trigger;
357	    if (exit_pc) {
358	      trigger.add_pc_hit(*exit_pc, HYBRID_HANDOFF_EXIT);
359	      spdlog::info("hybrid: PC-trigger mode, exit_pc=0x{:x}", *exit_pc);
360	    } else {
361	      auto elf = LIEF::ELF::Parser::parse(elf_path);
362	      if (!elf)
363	        throw std::runtime_error(
364	          "enable_hybrid_handoff: failed to parse " + elf_path);
365	      for (const auto& seg: elf->segments()) {
366	        if (seg.type() != LIEF::ELF::SEGMENT_TYPES::PT_LOAD) continue;
367	        if ((static_cast<unsigned>(seg.flags()) & 1u) == 0u) continue;  // PF_X
368	        const auto content = seg.content();
369	        const std::span<const uint8_t> bytes{content.data(), content.size()};
370	        trigger.scan_buffer(bytes, seg.virtual_address());
371	      }
372	    }
373	
374	    hybrid_dmi_bus_ = std::make_unique<
375	      hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width,
376	                            PLATFORM::dmi_data_width>>(platform.dmi,
377	                                                       platform.clk.period());
378	    hybrid_handoff_.emplace(std::move(trigger), *hybrid_dmi_bus_,
379	                            v_scratch_gpa(), active_caps());
380	    if (hybrid_input_state_)
381	      hybrid_handoff_->set_passthrough_input(*hybrid_input_state_);
382	    hybrid_handoff_->set_minimal_drain(drain_minimal);
383	    hybrid_handoff_->set_l2c(l2c_present(), l2c_base());  // v5: exit drain re-reads L2C
384	
385	    hybrid_state_path_ = state_out_path;
386	  }
387	
388	  // F6: override the config-derived caps with a manifest-driven transport set
389	  // (from --transport-csrs). When set, active_caps() returns this instead of
390	  // andes_caps_from_config() -- the runtime transport is then driven by the
391	  // registered manifest, not by re-modelling config macros.
392	  void set_transport_caps(const hybrid::AndesCaps& c) { transport_caps_ = c; }
393	
394	private:
395	  std::optional<hybrid::AndesCaps> transport_caps_{};
396	  auto active_caps() const -> hybrid::AndesCaps
397	  {
398	    return transport_caps_ ? *transport_caps_ : hybrid::andes_caps_from_config();
399	  }
400	
401	  // v5: L2C MMIO transport gate, derived from the build's Verilog config macros
402	  // (_NDS_*, supplied via cpu_config.hpp -- same source as andes_caps_from_
403	  // config). Present only when this engine is built with an L2 cache controller
404	  // AND its register base is known. Gated on _NDS_L2C_CACHE_SIZE_KB, not the
405	  // cluster's has_shared_cache, because that flag also covers L3 (ax46/ax66).
406	  // A store to an absent L2C region would fault the Program Buffer, so this
407	  // stays off on every current engine (_NDS_L2C_CACHE_SIZE_KB == 0).
408	  static constexpr bool l2c_present()
409	  {
410	#if defined(_NDS_L2C_CACHE_SIZE_KB) && defined(_NDS_L2C_REG_BASE)
411	    return (_NDS_L2C_CACHE_SIZE_KB) > 0;
412	#else
413	    return false;
414	#endif
415	  }
416	  static constexpr uint64_t l2c_base()
417	  {
418	#if defined(_NDS_L2C_REG_BASE)
419	    return static_cast<uint64_t>(_NDS_L2C_REG_BASE);
420	#else
421	    return 0;
422	#endif
423	  }
424	
425	  // L26: the GUEST address of the V-register transport page -- the top page of
426	  // the mapped RAM span. The driver maps one page above --mem-size (scheme D),
427	  // so this sits just past the program's declared RAM and never collides with
428	  // its data/stack. Single source of truth handed to ResumeDriver/StateDrain.
429	  auto v_scratch_gpa() const -> uint64_t
430	  {
431	    return hybrid::v_scratch_gpa(platform.main_memory.region.base_address,
432	                                 platform.main_memory.data.size());
433	  }
434	
435	  // LG3: drain the freshly reset, just-halted hart into a baseline the
436	  // liveness gate compares restores against. The probe carries the incoming
437	  // state's flags/vlenb so drain_with_passthrough reads exactly the blocks
438	  // the gate will compare (it is flag-driven); every probe field it does not
439	  // re-read stays zero, matching what an absent block compares against.
440	  auto capture_reset_baseline(
441	    hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width,
442	                          PLATFORM::dmi_data_width>& bus,
443	    const hybrid_state_v1& input) -> hybrid_state_v1
444	  {
445	    hybrid::StateDrain drain(bus, v_scratch_gpa(),
446	                             active_caps());
447	    // At reset mstatus.FS/VS are Off, so the capture's vse8 sweep (and the
448	    // FPR/V CSR abstract reads) would raise illegal instruction (cmderr=3).
449	    // Halt and enable them first, exactly like resume() does before its FPR/V
450	    // writes. Safe to clobber: mstatus is never re-read by a drain nor gated
451	    // by the baseline, and resume() rewrites it whenever the FP/V flags are
452	    // set -- the only case this branch runs.
453	    if (input.flags & (HYBRID_FLAG_FP | HYBRID_FLAG_V)) {
454	      using RD = hybrid::ResumeDriver;
455	      bus.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
456	      bus.write(RD::kDmcontrol,
457	                RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
458	      hybrid::poll_until_set(bus, RD::kDmstatus, RD::kDmstatusAllhalted,
459	                             "reset-baseline capture halt");
460	      const uint64_t mstatus = hybrid::read_register_64(
461	        bus, hybrid::regno_csr(RD::kCsrMstatus), "reset-baseline mstatus");
462	      uint64_t enable = mstatus;
463	      if ((input.flags & HYBRID_FLAG_FP)
464	          && (enable & RD::kMstatusFsMask) == 0)
465	        enable |= RD::kMstatusFsInitial;
466	      if ((input.flags & HYBRID_FLAG_V)
467	          && (enable & RD::kMstatusVsMask) == 0)
468	        enable |= RD::kMstatusVsInitial;
469	      if (enable != mstatus)
470	        hybrid::write_register_abstract(
471	          bus, hybrid::regno_csr(RD::kCsrMstatus), enable);
472	    }
473	    hybrid_state_v1 probe{};
474	    probe.magic = HYBRID_STATE_MAGIC;
475	    probe.version = HYBRID_STATE_VERSION;
476	    probe.flags = input.flags;
477	    probe.vlenb = input.vlenb;
478	    auto baseline = drain.drain_with_passthrough(probe);
479	    lift_scratch_blocks(baseline);
480	    return baseline;
481	  }
482	
483	  // Lift the scratch-page transport into `state` (dual of the resume
484	  // staging): the V dump sweep bytes back into state.vreg[] -- so the drained
485	  // state carries vsim's actual V values, not QEMU 1's stale snapshot. The V
486	  // regfile is the only state that rides the scratch page; GPRs, FPRs, and
487	  // every CSR drain via abstract reads directly into the state. Shared by the
488	  // exit drain and the reset-baseline capture.
489	  void lift_scratch_blocks(hybrid_state_v1& state)
490	  {
491	    const std::span<const uint8_t> ram{platform.main_memory.data.data(),
492	                                       platform.main_memory.data.size()};
493	    if ((state.flags & HYBRID_FLAG_V) != 0u)
494	      hybrid::read_v_from_scratch(state, ram);
495	  }
