511	  // skip_memory_load: parse the ELF and set the reset vector, but leave
512	  // platform.main_memory untouched. Used in tier-2 hybrid resume where
513	  // QEMU 1's -kernel already populated the shared mmap; re-loading would
514	  // zero-fill the .bss tail of each PT_LOAD and destroy phase-1 writes
515	  // to static buffers. The reset vector is still set so the hart has a
516	  // valid fetch target during the post-reset cycles that precede the DMI
517	  // halt+DPC-write resume sequence.
518	  void load_elf(const std::string& path, bool skip_memory_load = false)
519	  {
520	    const auto elf = LIEF::ELF::Parser::parse(path);
521	    if (!elf) {
522	      spdlog::critical("Check if it's a valid ELF file path : {}", path);
523	      exit(1);
524	    }
525	
526	    if (!skip_memory_load)
527	      read_elf_into_memory(
528	        *elf,
529	        static_cast<xlen_t>(platform.main_memory.region.base_address),
530	        platform.main_memory.data);
531	    for (auto& rv: platform.reset_vector)
532	      rv.write(elf->entrypoint());
533	  }
