535	  void set_reset_vector(size_t hart, uint64_t addr)
536	  {
537	    if (hart >= platform.reset_vector.size()) {
538	      spdlog::critical("hart {} out of range (max {})", hart,
539	                       platform.reset_vector.size() - 1);
540	      std::exit(EXIT_FAILURE);
541	    }
542	    platform.reset_vector[hart].write(addr);
543	  }
