545	  // F5 (ROADMAP_ilm_dlm) + F4 (ROADMAP_hvm): dump the local memories' and
546	  // HVM's content next to the handoff-out state file -- the read duals of
547	  // the --ilm/--dlm/--hvm backdoor load, same "<state>.ilm/.dlm/.hvm"
548	  // sidecar convention as the QEMU plugin's entry drain. Zero sim cycles
549	  // (hierarchical-reference read, ECC stripped). A wrapper without the
550	  // get_* dumps nothing. Called by check_hybrid_handoff right after the
551	  // state-file write, so the "state file plus sidecars ride together"
552	  // contract has a single producer.
553	  void dump_lm_sidecars(const std::string& state_path)
554	  {
555	    auto dump = [](const std::string& path, const std::vector<uint8_t>& data) {
556	      std::ofstream f(path, std::ios::binary | std::ios::trunc);
557	      f.write(reinterpret_cast<const char*>(data.data()),
558	              static_cast<std::streamsize>(data.size()));
559	      if (!f) throw std::runtime_error("cannot write " + path);
560	    };
561	    if constexpr (kCpuCanDumpIlm<CPU>)
562	      dump(state_path + ".ilm", cpu.get_ilm());
563	    if constexpr (kCpuCanDumpDlm<CPU>)
564	      dump(state_path + ".dlm", cpu.get_dlm());
565	    if constexpr (kCpuCanDumpHvm<CPU>)
566	      dump(state_path + ".hvm", cpu.get_hvm());
567	  }
