569	  void load_image(const std::string& path, MEM_TYPE type)
570	  {
571	    switch (type) {
572	    case MEM_TYPE::ILM:
573	      if constexpr (kCpuCanLoadIlm<CPU>) {
574	        read_binary_file(path, [this](const auto& data) { cpu.set_ilm(data); });
575	      } else {
576	        throw std::runtime_error(
577	          "CPU does not support ILM - cannot load ILM ROM image");
578	      }
579	      break;
580	
581	    case MEM_TYPE::DLM:
582	      if constexpr (kCpuCanLoadDlm<CPU>) {
583	        read_binary_file(path, [this](const auto& data) { cpu.set_dlm(data); });
584	      } else {
585	        throw std::runtime_error(
586	          "CPU does not support DLM - cannot load DLM ROM image");
587	      }
588	      break;
589	
590	    case MEM_TYPE::HVM:
591	      if constexpr (kCpuCanLoadHvm<CPU>) {
592	        read_binary_file(path, [this](const auto& data) { cpu.set_hvm(data); });
593	      } else {
594	        throw std::runtime_error(
595	          "CPU does not support HVM - cannot load HVM image");
596	      }
597	      break;
598	
599	    case MEM_TYPE::RAM:
600	      read_binary_file(path, [this](const auto& data) {
601	        if (data.size() > platform.main_memory.data.size())
602	          throw std::runtime_error("RAM image size exceeds main memory size");
603	        std::copy(data.begin(), data.end(), platform.main_memory.data.begin());
604	      });
605	      break;
606	
607	    default:
608	      throw std::runtime_error("Unknown memory type");
609	    }
610	  }
