612	  void reset()
613	  {
614	    static constexpr int core_num = CPU::NDS_NHART;
615	    static constexpr int reset_val = (1 << core_num) - 1;
616	
617	    platform.resetn.write(0);
618	    auto saved = context_config;
619	    context_config = {};
620	    this->run(1);
621	    context_config = saved;
622	
623	    for (size_t i = 0; i < platform.reset_vector.size(); ++i)
624	      spdlog::info("hart {} reset vector: {:#x}", i,
625	                   (uint64_t) platform.reset_vector[i].read());
626	
627	    platform.resetn.write(reset_val);
628	
629	    if (context_config.continue_from)
630	      restore_context(context_config.dir);
631	  }
632	
633	  int run(const uint64_t max_cycles = std::numeric_limits<uint64_t>::max())
634	  {
635	    auto sa = memzeroed<struct sigaction>();
636	    sa.sa_handler = sigint_handler;
637	    sigemptyset(&sa.sa_mask);
638	
639	    auto oact = memzeroed<struct sigaction>();
640	    if (sigaction(SIGINT, &sa, &oact) == -1)
641	      perror("sigaction");
642	
643	    const auto restore_sigint = std::experimental::scope_exit{[&] {
644	      if (sigaction(SIGINT, &oact, nullptr) == -1)
645	        perror("sigaction");
646	    }};
647	
648	    // wait for debugger connections
649	    while (dtm_debug && !dtm.is_connected()) {
650	      dtm.try_accept_socket();
651	      if (ctrlc != 0) {
652	        return 130;
653	      }
654	      sleep(1);
655	    }
656	
657	    [[maybe_unused]]
658	    bool ctx_resuming = context_config.continue_from;
659	    [[maybe_unused]]
660	    bool ctx_triggered = false;
661	
662	    for (auto n = uint64_t{0}; n < max_cycles; ++n) {
663	
664	      if (ctx_resuming) [[unlikely]] {
665	        // Pull up PLIC interrupt signal at the first cycle of the resume
666	        platform.int_trigger.write(1);
667	        ctx_resuming = false;
668	        ctx_triggered = true;
669	      }
670	
671	      sc_core::sc_start(platform.clk.period());
672	
673	      trace_.on_cycle(cpu);
674	
675	      if (hybrid_handoff_) [[unlikely]] {
676	        if (auto code = check_hybrid_handoff(); code) return *code;
677	      }
678	
679	      if (context_config.save_on_wfi && platform.wfi_signal.read() == true)
680	        [[unlikely]]
681	      {
682	        context_config.save(platform, cpu);
683	        spdlog::info("User save context");
684	        return 0;
685	      }
686	
687	      if (ctrlc != 0) {
688	        ctrlc = 0;
689	        spdlog::info("Ctrl+C PC: {:x}", get_current_pc());
690	        trace_.log_committed_pcs(cpu);
691	        return 130;
692	      }
693	
694	      if (ctx_triggered) [[unlikely]] {
695	        // Pull down the interrupt signal after 1 cycle
696	        platform.int_trigger.write(0);
697	        ctx_triggered = false;
698	      }
699	
700	      if (platform.sim_control.exits >= 0) {
701	        spdlog::info("sim_control: got exit {}, stopping",
702	                     platform.sim_control.exits);
703	        spdlog::info("Exit PC: {:x}", get_current_pc());
704	        trace_.log_committed_pcs(cpu);
705	        return platform.sim_control.exits;
706	      }
707	
708	      if (this->cpu.contextp()->gotFinish())
709	        return 0;
710	
711	      spdlog::trace("PC: {:x}", get_current_pc());
712	    }
713	    return 0;
714	  }
