723	
724	  auto check_hybrid_handoff() -> std::optional<int>
725	  {
726	    if constexpr (!requires { cpu.get_committed_pc(); }) {
727	      return std::nullopt;
728	    } else {
729	      const auto committed = cpu.get_committed_pc();
730	      if (committed.empty()) return std::nullopt;
731	      for (const auto pc: committed[0]) {
732	        auto state = hybrid_handoff_->on_retire(pc);
733	        if (state) {
734	          // V-register merge: pull the V dump sweep's scratch bytes into the
735	          // drained state (see lift_scratch_blocks).
736	          lift_scratch_blocks(*state);
737	          spdlog::info("hybrid handoff: drained at pc=0x{:x}, writing {}",
738	                       pc, hybrid_state_path_);
739	          std::ofstream f(hybrid_state_path_, std::ios::binary);
740	          f.write(reinterpret_cast<const char*>(&*state), sizeof(*state));
741	          // F5: the LM sidecars ride with every drain -- one producer for
742	          // the "state file plus sidecars" contract.
743	          dump_lm_sidecars(hybrid_state_path_);
744	          return hybrid::kExitHandoffToQemu;
745	        }
746	      }
747	      return std::nullopt;
748	    }
749	  }
